import{c as o,Q as s,j as r,m as e}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Cold Start 對 Workspace 執行效率影響 — 完整評估 + 改善計劃書","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-06-coldstart-execution-efficiency-audit.md","filePath":"research/reports/2026-06-06-coldstart-execution-efficiency-audit.md","lastUpdated":1780842316000}'),a={name:"research/reports/2026-06-06-coldstart-execution-efficiency-audit.md"};function n(d,t,i,l,c,h){return s(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="cold-start-對-workspace-執行效率影響-—-完整評估-改善計劃書" tabindex="-1">Cold Start 對 Workspace 執行效率影響 — 完整評估 + 改善計劃書 <a class="header-anchor" href="#cold-start-對-workspace-執行效率影響-—-完整評估-改善計劃書" aria-label="Permalink to &quot;Cold Start 對 Workspace 執行效率影響 — 完整評估 + 改善計劃書&quot;">​</a></h1><blockquote><p>日期：2026-06-06 ｜ 分支：<code>feature/coldstart-audit</code> ｜ 方法：The Loop OBSERVE→IDENTIFY（主對話親量測 + researcher 盤點 + advisor 校正） <strong>Cold start 定義</strong>：每次 Claude Code session 啟動到第一個 user prompt 提交前，workspace 強加的所有開銷——分為<strong>時間維度</strong>（wall-clock 啟動延遲）與<strong>空間維度</strong>（注入 context window 的 byte）。兩者是不同問題、不同修法，本報告全程分離。</p></blockquote><hr><h2 id="_0-一頁式結論-tl-dr" tabindex="-1">0. 一頁式結論（TL;DR） <a class="header-anchor" href="#_0-一頁式結論-tl-dr" aria-label="Permalink to &quot;0. 一頁式結論（TL;DR）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>現況</th><th>最大宗</th><th>可控改善</th><th>性質</th></tr></thead><tbody><tr><td><strong>時間</strong></td><td>session-init <strong>~520ms</strong>（cache-hit 仍如此）</td><td>schema-lint 迴圈 <strong>416ms（80%）</strong></td><td>批次化 → <strong>44ms（−89%，省 ~372ms）</strong></td><td>每 session 一次，非每 prompt</td></tr><tr><td><strong>空間</strong></td><td>cold-start 注入 <strong>~39KB</strong></td><td>auto-load 18.7KB / MEMORY 11KB / skills 9KB</td><td>MEMORY「上次更新」節 4.4KB 冗餘可壓</td><td>靜態為主，prompt-cache 後幾乎不再計 token</td></tr></tbody></table><p><strong>一句話</strong>：時間維度有一個<strong>乾淨的免費勝利</strong>（schema-lint 批次化，省半秒啟動稅）；空間維度的大宗多為 <strong>load-bearing 或已被 prompt cache 攤銷</strong>，真正該動的是 MEMORY 冗餘，其餘是 cap 紀律問題而非速度問題。<strong>不要把兩者混為「執行效率」。</strong></p><hr><h2 id="_1-量測方法與證據-可重現" tabindex="-1">1. 量測方法與證據（可重現） <a class="header-anchor" href="#_1-量測方法與證據-可重現" aria-label="Permalink to &quot;1. 量測方法與證據（可重現）&quot;">​</a></h2><p>全部數字由<strong>主對話親跑</strong>（確定性 gate 不經 sub-agent，core.md TEST 段 unverified_success 閘門）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>session-init.sh × 3:    525 / 513 / 521 ms   (cache-hit 模式)</span></span>
<span class="line"><span>eval-reminder:          30 ms   (本次 0 byte 輸出 — baseline 未逾 30 天)</span></span>
<span class="line"><span>user-prompt-submit:     120 ms</span></span>
<span class="line"><span>單次 python3 -c pass:    23 ms   (10 次 231ms 平均)</span></span>
<span class="line"><span>schema-lint 區段(15檔):  416 ms  ← 80% of session-init</span></span>
<span class="line"><span>  └ 改單一 python3 批次:  44 ms   (−372ms, −89%)</span></span></code></pre></div><p><code>claude-progress.json</code> <strong>不存在</strong> → reminders/active-task 兩個 python3 區段被 <code>[ -f ]</code> 跳過（無浪費）。</p><hr><h2 id="_2-時間維度-—-完整項目評估" tabindex="-1">2. 時間維度 — 完整項目評估 <a class="header-anchor" href="#_2-時間維度-—-完整項目評估" aria-label="Permalink to &quot;2. 時間維度 — 完整項目評估&quot;">​</a></h2><p>session-init.sh（510 行）內共 <strong>12 個 python3 子程序</strong>呼叫。每次 spawn python3 ≈ 23ms。cache-hit 路徑下實際觸發者：</p><table tabindex="0"><thead><tr><th>#</th><th>區段</th><th>python3 次數</th><th>觸發條件</th><th>耗時估</th><th>評估</th></tr></thead><tbody><tr><td>1</td><td>model-check</td><td>1</td><td>必跑</td><td>~23ms</td><td>必要，保留</td></tr><tr><td>2</td><td>HMF 到期檢查</td><td>1</td><td>harness-model-fit.json 存在</td><td>~23ms</td><td>必要，保留</td></tr><tr><td>3</td><td>cache-baseline monthly</td><td>1</td><td>baseline.csv + progress.json</td><td>~0ms</td><td>progress.json 不存在 → <strong>跳過</strong></td></tr><tr><td>4</td><td>reminders echo</td><td>1</td><td>progress.json 存在</td><td>~0ms</td><td><strong>跳過</strong></td></tr><tr><td>5</td><td>active-task</td><td>1</td><td>progress.json 存在</td><td>~0ms</td><td><strong>跳過</strong></td></tr><tr><td>6</td><td><strong>schema-lint</strong></td><td><strong>15</strong>（每 agent 一次！）</td><td>agents/ 目錄存在</td><td><strong>416ms</strong></td><td>⚠️ <strong>80% 開銷源</strong></td></tr><tr><td>7</td><td>model-version reminder</td><td>1</td><td>model 異動時</td><td>0ms</td><td>條件觸發，未動</td></tr></tbody></table><p><strong>根因</strong>：schema-lint 用 <code>while read … python3 …</code> 對 15 個 agent 檔<strong>各 spawn 一次 python3 直譯器</strong>。這是純靜態 lint（檢查 frontmatter 必填欄），agent 檔極少變動，每次 cold start 全量重跑 = 純浪費。15 × 23ms ≈ 345ms 全是直譯器啟動成本，非實際工作（單批次只需 44ms）。</p><p><strong>AI 程式碼四大缺陷自檢</strong>（PROPOSE 紀律）：此處命中 <strong>brittle</strong>（per-file spawn 是天真實作）。working（功能對）≠ good。</p><hr><h2 id="_3-空間維度-—-完整-context-注入總帳" tabindex="-1">3. 空間維度 — 完整 context 注入總帳 <a class="header-anchor" href="#_3-空間維度-—-完整-context-注入總帳" aria-label="Permalink to &quot;3. 空間維度 — 完整 context 注入總帳&quot;">​</a></h2><table tabindex="0"><thead><tr><th>來源</th><th>Bytes</th><th>性質</th><th>可控？</th></tr></thead><tbody><tr><td>auto-load rules（CLAUDE.md + 4 rules）</td><td><strong>18,726</strong></td><td>STATIC，prompt-cache 命中</td><td>受 19,000 cap 約束</td></tr><tr><td>MEMORY.md</td><td><strong>10,976</strong></td><td>半靜態（session 末更新）</td><td>✅ 可壓</td></tr><tr><td><strong>workspace skills name+description</strong></td><td><strong>9,167</strong></td><td>STATIC，prompt-cache 命中</td><td>✅ 可控但 <strong>load-bearing</strong></td></tr><tr><td>session-init stdout（cache-hit）</td><td>~612</td><td>動態為主，<strong>不可快取</strong></td><td>部分可控</td></tr><tr><td>eval-reminder stdout</td><td>0–100</td><td>條件動態</td><td>—</td></tr><tr><td>deferred tools list</td><td>小</td><td>harness-owned</td><td>❌ 不可控</td></tr><tr><td>UserPromptSubmit（每 prompt）</td><td>150 + 條件</td><td>per-prompt</td><td>可控</td></tr><tr><td><strong>Cold-start 總計（不含 per-prompt）</strong></td><td><strong>~39,000</strong></td><td>—</td><td>—</td></tr></tbody></table><h3 id="_3-1-三大項逐一評估" tabindex="-1">3.1 三大項逐一評估 <a class="header-anchor" href="#_3-1-三大項逐一評估" aria-label="Permalink to &quot;3.1 三大項逐一評估&quot;">​</a></h3><p><strong>(A) auto-load 18.7KB — 距 19,000 cap 僅剩 274B</strong></p><ul><li>已逼滿。<strong>這是 cap 紀律問題，不是速度問題</strong>：prompt cache 首次寫入後，後續 session 命中快取，幾乎不再計 input token 成本，也不增 per-session latency。</li><li>真正風險：<strong>無 headroom</strong>。下次任何 auto-load 增補都會破 cap → 需先回收。MEMORY 待辦已記「19,000 近滿監控」。</li></ul><p><strong>(B) MEMORY.md 11KB — 唯一真冗餘</strong></p><ul><li>88 行（未達 &gt;200 compactor 線），但「上次更新」單節 <strong>4,399B = 全檔 40%</strong>，含 3 個長 session 摘要，<strong>每節遠超 CLAUDE.md 規定 ≤30 行/節</strong>。</li><li>早期「待辦」節 6 個 <code>[x]</code> 已結清項仍佔 534B。</li><li><strong>這是唯一明確的「冗餘可刪」</strong>，且 MEMORY 每 session 注入、session 末改寫（半靜態，cache 攤銷較差）。</li></ul><p><strong>(C) skills 9.2KB — 最大盲點，但 load-bearing</strong></p><ul><li>⚠️ <strong>researcher 初判「workspace 無法控制」錯誤</strong>（subagent verdict 非證據，已親 grep 推翻）。實測：27 個 workspace SKILL.md 的 <code>name+description</code> 注入 cold-start skill list = <strong>9,167B（平均 339B/skill）</strong>，<strong>workspace 完全可控</strong>。</li><li><strong>但這是 load-bearing context</strong>：description 是 Skill tool 的 routing 依據。schema-lint 自己警告「description &lt;20 字 → reduce routing accuracy」。盲目精簡會損害 skill 路由準確度。</li><li>最重的 5 個：gap-vote(475B)、sia(463B)、harness-meta(450B)、autoload-evolution(445B)、verified-merge(427B)。</li><li><strong>誠實結論</strong>：skills 是 cold-start 第三大塊、可控，但<strong>多數 load-bearing</strong>——精簡空間有限，且需逐一判斷 routing 影響，非機械可刪。<strong>列入觀察，非首批動作。</strong></li></ul><hr><h2 id="_4-改善建議-依優先序-槓桿標註" tabindex="-1">4. 改善建議（依優先序 + 槓桿標註） <a class="header-anchor" href="#_4-改善建議-依優先序-槓桿標註" aria-label="Permalink to &quot;4. 改善建議（依優先序 + 槓桿標註）&quot;">​</a></h2><blockquote><p>每項標明拉哪根槓桿：<strong>[L]=latency 速度</strong> / <strong>[C]=context cap 紀律</strong>。混淆兩者是本評估最易犯的錯。</p></blockquote><h3 id="p1-—-schema-lint-批次化-⭐-首推-l" tabindex="-1">P1 — schema-lint 批次化 ⭐ 首推 [L] <a class="header-anchor" href="#p1-—-schema-lint-批次化-⭐-首推-l" aria-label="Permalink to &quot;P1 — schema-lint 批次化 ⭐ 首推 [L]&quot;">​</a></h3><ul><li><strong>動作</strong>：將 session-init.sh 的 <code>while read … python3</code> 迴圈改為<strong>單一 python3 一次處理全部 agent 檔</strong>。</li><li><strong>效益</strong>：416ms → 44ms，<strong>省 ~372ms 啟動延遲（−89%）</strong>。</li><li><strong>誠實定價</strong>：這是「<strong>每 session 一次省半秒</strong>」，不是 per-prompt，也不是「巨大」。值得做是因為<strong>免費</strong>（純實作改寫，零行為改變），不是因為大。</li><li><strong>風險</strong>：極低。輸出語意不變（同樣印 <code>⚠️ N agent(s) with schema issues</code>）。外科刀改動，~15 行。</li><li><strong>進階選項（不必首批做）</strong>：mtime-gate（agent 檔未變則整段跳過，~100% 省）或移到 PostToolUse-on-agent-edit。複雜度略高，P1 批次化已收 89%，<strong>先做最簡</strong>。</li></ul><h3 id="p2-—-memory-md「上次更新」節壓縮-c" tabindex="-1">P2 — MEMORY.md「上次更新」節壓縮 [C] <a class="header-anchor" href="#p2-—-memory-md「上次更新」節壓縮-c" aria-label="Permalink to &quot;P2 — MEMORY.md「上次更新」節壓縮 [C]&quot;">​</a></h3><ul><li><strong>動作</strong>：委派 <code>memory-compactor</code> 壓「上次更新」節（4.4KB→目標 ≤1.5KB）+ 刪早期已結清 <code>[x]</code> 待辦（534B）。</li><li><strong>效益</strong>：MEMORY 11KB → ~8KB，恢復「≤30 行/節」紀律。</li><li><strong>風險</strong>：低，但 <strong>memory-compactor verdict 非證據</strong>——壓完主對話親 grep 確認決策/待辦未遺失（Lesson 2026-06-04-D）。</li><li><strong>注意</strong>：此為 cap 紀律 + 可讀性，<strong>非速度</strong>——MEMORY 注入早被 prompt cache 攤銷。</li></ul><h3 id="p3-—-auto-load-headroom-回收-已在-memory-待辦-c" tabindex="-1">P3 — auto-load headroom 回收（已在 MEMORY 待辦）[C] <a class="header-anchor" href="#p3-—-auto-load-headroom-回收-已在-memory-待辦-c" aria-label="Permalink to &quot;P3 — auto-load headroom 回收（已在 MEMORY 待辦）[C]&quot;">​</a></h3><ul><li><strong>動作</strong>：執行 MEMORY 既有待辦「壓 TYPE B/C/D 取回餘裕」或 DEFER 控制語義表（~250B）。</li><li><strong>效益</strong>：274B → 更安全 headroom，容下次 auto-load 增補。</li><li><strong>不在本報告新建</strong>——已有 proposal（<code>2026-06-04-12-rule-canon-patch-proposal.md</code>），不重複造輪子。</li></ul><h3 id="p4-—-skills-description-觀察項-不立即動-c" tabindex="-1">P4 — skills description 觀察項（<strong>不立即動</strong>）[C] <a class="header-anchor" href="#p4-—-skills-description-觀察項-不立即動-c" aria-label="Permalink to &quot;P4 — skills description 觀察項（**不立即動**）[C]&quot;">​</a></h3><ul><li><strong>判斷</strong>：9.2KB 可控但 load-bearing。精簡 5 個最重 description 至多省 ~1KB，且需逐一驗 routing 不退化。</li><li><strong>建議</strong>：<strong>列入觀察，非動作</strong>。未來若 auto-load cap 真的撐不住，再以「逐 skill 驗 routing」方式微調最冗長者。當前不值得碰。</li></ul><h3 id="不建議動的項目-完整性聲明" tabindex="-1">不建議動的項目（完整性聲明） <a class="header-anchor" href="#不建議動的項目-完整性聲明" aria-label="Permalink to &quot;不建議動的項目（完整性聲明）&quot;">​</a></h3><ul><li>model-check / HMF 檢查（各 23ms）：必要功能，移除即失去 model-drift 偵測與 HMF 到期提醒。</li><li>eval-reminder：本次 0 byte，條件觸發合理。</li><li>auto-load 內容本身：D5 paper + #446 已背書「不動內容」（MEMORY 2026-06-05 記載）。</li><li>deferred tools list：harness-owned，不可控。</li></ul><hr><h2 id="_5-執行計劃書" tabindex="-1">5. 執行計劃書 <a class="header-anchor" href="#_5-執行計劃書" aria-label="Permalink to &quot;5. 執行計劃書&quot;">​</a></h2><h3 id="phase-1-—-schema-lint-批次化-p1-本-session-可完成" tabindex="-1">Phase 1 — schema-lint 批次化（P1，本 session 可完成） <a class="header-anchor" href="#phase-1-—-schema-lint-批次化-p1-本-session-可完成" aria-label="Permalink to &quot;Phase 1 — schema-lint 批次化（P1，本 session 可完成）&quot;">​</a></h3><p><strong>成功條件（可機械驗證）</strong>：</p><ol><li><code>bash .claude/hooks/session-init.sh</code> 輸出語意不變（仍印 skill count、HARNESS_MODEL_VERSION、commit log）。</li><li>重量測 session-init 總耗時 <strong>&lt; 200ms</strong>（從 ~520ms 降）。</li><li>schema-lint 對「故意缺 frontmatter 的測試 agent 檔」仍能印 WARN（功能不退化）。</li><li><code>bash scripts/healthcheck.sh</code> 通過。</li></ol><p><strong>步驟</strong>：</p><ol><li>OBSERVE：讀 session-init.sh L479–509 schema-lint 區段，確認輸出格式契約。</li><li>PROPOSE：單一 python3 heredoc，內部 glob <code>agents/*.md</code>、迴圈檢查、累計 <code>SCHEMA_ISSUES</code>、印同格式 WARN。</li><li>APPLY：Edit 替換迴圈（~15 行 diff，外科刀）。</li><li>TEST：主對話親跑前/後耗時對照 + 故意壞檔測 WARN + healthcheck（展示前5/後5行）。</li><li>RECORD：Checkpoint + MEMORY session 記錄。</li></ol><p><strong>回滾</strong>：<code>git revert</code> 單一 commit；session-init 改動隔離，無連帶。</p><h3 id="phase-2-—-memory-壓縮-p2-可同-session-或獨立" tabindex="-1">Phase 2 — MEMORY 壓縮（P2，可同 session 或獨立） <a class="header-anchor" href="#phase-2-—-memory-壓縮-p2-可同-session-或獨立" aria-label="Permalink to &quot;Phase 2 — MEMORY 壓縮（P2，可同 session 或獨立）&quot;">​</a></h3><p><strong>成功條件</strong>：</p><ol><li>MEMORY.md 總 byte &lt; 9,000（從 10,976）。</li><li>主對話親 grep 確認：4 個現行待辦全在、Lesson D–H 全在、核心決策全在。</li><li>每節 ≤30 行（核對「上次更新」節）。</li></ol><p><strong>步驟</strong>：委派 <code>memory-compactor</code> → 主對話 grep 驗證（verdict 非證據）→ commit。</p><h3 id="phase-3-—-auto-load-headroom-p3-承接既有-proposal-獨立排程" tabindex="-1">Phase 3 — auto-load headroom（P3，承接既有 proposal，獨立排程） <a class="header-anchor" href="#phase-3-—-auto-load-headroom-p3-承接既有-proposal-獨立排程" aria-label="Permalink to &quot;Phase 3 — auto-load headroom（P3，承接既有 proposal，獨立排程）&quot;">​</a></h3><p>走既有 <code>2026-06-04-12-rule-canon-patch-proposal.md</code> + <code>/autoload-evolution</code> 閉環，本報告不重複。</p><h3 id="gate-與紀律" tabindex="-1">Gate 與紀律 <a class="header-anchor" href="#gate-與紀律" aria-label="Permalink to &quot;Gate 與紀律&quot;">​</a></h3><ul><li>三 Phase 均<strong>非破壞性</strong>（無 DELETE/prod/key），無需不可逆 gate，但完成前各跑驗證展示輸出。</li><li>全程 <code>feature/coldstart-audit</code> 分支，commit 前 <code>git branch --show-current</code> 確認。</li></ul><hr><h2 id="_5-5-執行結果-2026-06-06-同-session-完成" tabindex="-1">5.5 執行結果（2026-06-06 同 session 完成） <a class="header-anchor" href="#_5-5-執行結果-2026-06-06-同-session-完成" aria-label="Permalink to &quot;5.5 執行結果（2026-06-06 同 session 完成）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>狀態</th><th>實測</th></tr></thead><tbody><tr><td><strong>P1 schema-lint 批次化</strong></td><td>✅ 完成</td><td>session-init <strong>520→170ms（−68%）</strong>；輸出契約不變（3 種壞檔 + issue count 驗證一致）；healthcheck 116-0</td></tr><tr><td><strong>P2 MEMORY 壓縮</strong></td><td>✅ 完成</td><td><strong>10,976→9,052B（−18%）</strong>；刪早期已結清待辦節 + 壓 3 個長 session 摘要；grep 驗 4 待辦/Lesson G/H/D/commit ref 全保留</td></tr><tr><td><strong>P3 auto-load headroom</strong></td><td>⚠️ 誠實 no-op</td><td>auto-load <strong>零連續空行/零 trailing whitespace/<code>---</code> 為語意分段</strong> → <strong>無純機械冗餘可回收</strong>。274B 餘裕是「逼滿但乾淨」，列觀察。守 CLAUDE.md「不為塞 byte 反推湊」+ Lesson 2026-06-05-A「先質疑約束本身」</td></tr></tbody></table><p><strong>P3 no-op 的正當性</strong>：使用者選「純機械回收」，但實測發現該 auto-load 已是優化態。硬壓會損語意分段或規則措辭——這違反「外科刀」與「不湊 byte」紀律。<strong>誠實回報「沒有可回收空間」優於製造假動作。</strong> 真正的 headroom 回收須走內容變更（既有 canon-patch proposal，需逐條核准），不在「純機械」範圍。</p><p>實測差異說明：P1 報告 P2 預測「44ms / −89%」是 schema-lint 區段隔離值；實裝後 session-init <strong>整體</strong> 170ms（含 model-check/HMF/git log 等其餘必要區段），整體降幅 −68%，與預測一致方向。</p><hr><h2 id="_6-附錄-—-評估方法論的自我校正記錄" tabindex="-1">6. 附錄 — 評估方法論的自我校正記錄 <a class="header-anchor" href="#_6-附錄-—-評估方法論的自我校正記錄" aria-label="Permalink to &quot;6. 附錄 — 評估方法論的自我校正記錄&quot;">​</a></h2><p>本評估本身命中兩個 The Loop 失敗模式，記錄供未來注入：</p><ol><li><strong>subagent verdict 非證據（已防）</strong>：researcher 判「skills 注入 workspace 無法控制」，與主對話親見的 SessionStart skill list 矛盾。advisor 攔下 → 主對話親 grep 推翻，補上 9.2KB 最大盲點。<strong>若信 researcher verdict，這份「完整評估」會漏掉第三大項。</strong></li><li><strong>latency vs context 混淆（已防）</strong>：初稿傾向把 schema-lint 416ms 講成「深度影響執行效率」。advisor 校正：那是<strong>每 session 一次省半秒</strong>，非 per-prompt；而 context 大宗多被 prompt cache 攤銷，是 cap 紀律問題非速度。<strong>兩維度全程分離標註 [L]/[C]。</strong></li></ol>`,65)])])}const m=o(a,[["render",n]]);export{p as __pageData,m as default};
